#include <cuda_runtime.h>
#include "../qem-cuda/gpu_solver.cu"
#include "../qem-cuda/reference.h"
#include <vector>
#include <chrono>
#include <cstdio>
#include <string>
#include <cstdlib>
#include <cmath>
// Independent Float64 source-behavior oracle; not a corrected minimizer.
double behavior(double A,double B,double C,double D){double b=.75*B/A,c=.5*C/A,d=.25*D/A,q=round((c/3-b*b/9)*1e5)/1e5,r=round((b*c/6-b*b*b/27-.5*d)*1e5)/1e5,disc=r*r+q*q*q;if(disc<=1e-5){double v[3],t=acos(r/sqrt(-q*q*q));for(int k=0;k<3;k++)v[k]=2*sqrt(-q)*cos((t+k*2*double(float(3.1415927)))/3)-b/3;std::sort(v,v+3);double lo=v[0],hi=v[2],delta=A*(pow(hi,4)-pow(lo,4))/4+B*(pow(hi,3)-pow(lo,3))/3+C*(hi*hi-lo*lo)/2+D*(hi-lo);return delta<=0?hi:lo;}return cbrt(r+sqrt(disc))+cbrt(r-sqrt(disc))-b/3;}
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):3,n=1027;float coeffs[8][4]={{1,-9,28,-33},{1,1,1,1},{1,0,-2,0},{2,2,2,2},{1,0,2,1},{1,0,-4,1},{1,0,3,-2},{2,0,-8,2}};float*in[5],*out[2];for(auto&p:in)cudaMallocHost(&p,n*4);for(auto&p:out)cudaMallocHost(&p,n*4);std::vector<float>cpu(n),prefix{float(n)};std::vector<double>gold(n);for(int i=0;i<n;i++){for(int j=0;j<4;j++)in[j][i]=coeffs[i%8][j];in[4][i]=float(i%17-8)*.25f;gold[i]=behavior(in[0][i],in[1][i],in[2][i],in[3][i]);}for(auto p:in)prefix.insert(prefix.end(),p,p+n);QuarticMinimumCPU(n,in[0],in[1],in[2],in[3],in[4],cpu.data());auto call=[&](){QuarticMinimumGPU(n,in[0],in[1],in[2],in[3],in[4],out[0]);QuarticMinimumGPUStreams(n,in[0],in[1],in[2],in[3],in[4],out[1]);};call();cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)call();cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep,ma=0,cpuerr=0;bool ok=cudaGetLastError()==cudaSuccess;auto art=prefix;for(auto p:out){for(int i=0;i<n;i++){ok&=std::isfinite(p[i])&&std::isfinite(cpu[i])&&std::isfinite(gold[i]);ma=std::max(ma,fabs(double(p[i])-gold[i]));cpuerr=std::max(cpuerr,fabs(double(p[i])-cpu[i]));}art.insert(art.end(),p,p+n);}ok&=ma<=1e-3&&cpuerr<=1e-3;const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"source_CPU_max_abs_error\":%.17g,\"timing_region\":\"sum_serial_and_four_plus_remainder_streams_fullhost_20alloc_H2D_two_stages_D2H_free_stream_lifecycle\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",2*n,ma,cpuerr,rep,path.c_str(),art.size());if(!ok)return 2;}for(auto p:in)cudaFreeHost(p);for(auto p:out)cudaFreeHost(p);}
